const D = { energy: .6, density: .55, scale: 1, speed: 1, persist: .82, hue: 250, x: .5, y: .5, style: 'cosmic', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = 200, BH = Math.max(96, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.dens = new Float32Array(BW * BH); S.chr = new Float32Array(BW * BH); S.zdp = new Float32Array(BW * BH);
  S.bw = BW; S.bh = BH; S.needBurn = true; S.px = 0.1; S.py = 0; S.pz = 0;
}

// Aizawa ODE constants
const aC = 0.95, bC = 0.70, cC = 0.60, dC = 3.5, eC = 0.25, fC = 0.1, dt = 0.01;

if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1); S.pj = fr(2) * 2 - 1;
  S.px = 0.05 + fr(3) * 0.2; S.py = fr(4) * 0.15 - 0.075; S.pz = fr(5) * 0.2;
  S.needBurn = true;
}
// burn-in: settle the trajectory onto the attractor before it contributes
if (S.needBurn) {
  S.needBurn = false;
  let bx = S.px, by = S.py, bz = S.pz;
  for (let s = 0; s < 400; s++) {
    const dx = (bz - bC) * bx - dC * by;
    const dy = dC * bx + (bz - bC) * by;
    const dz = cC + aC * bz - (bz * bz * bz) / 3 - (bx * bx + by * by) * (1 + eC * bz) + fC * bz * bx * bx * bx;
    bx += dx * dt; by += dy * dt; bz += dz * dt;
  }
  S.px = bx; S.py = by; S.pz = bz;
}

const g = S.g, dens = S.dens, chr = S.chr, zdp = S.zdp;
const styleI = P.style === 'plasma' ? 1 : P.style === 'ember' ? 2 : P.style === 'ice' ? 3 : P.style === 'pencil' ? 4 : 0;
const sec = K.section;

// slow dramaturgical morph of a,b -> the shell/spiral geometry evolves over minutes (kept in stable range)
let av = aC + 0.03 * Math.sin(K.t * 0.019) + (sec - 3.5) * 0.004 + S.pj * 0.012;
let bv = bC + 0.05 * Math.sin(K.t * 0.013 + 1.1) + S.pj * 0.02;
av = Math.max(0.90, Math.min(1.00, av));
bv = Math.max(0.60, Math.min(0.78, bv));

// TWO incommensurate continuous rotations = the motion floor (monotonic on K.t -> never re-phases at 8s)
const yawR = 0.16 + P.speed * 0.15;
const rollR = 0.107 + P.speed * 0.093;
const yaw = K.t * yawR + A.rms * 0.35 * Math.sin(K.t * 0.6);
const roll = K.t * rollR;
const pit = 0.46 + 0.24 * Math.sin(K.t * 0.037);
const cY = Math.cos(yaw), sY = Math.sin(yaw), cP = Math.cos(pit), sP = Math.sin(pit), cR = Math.cos(roll), sR = Math.sin(roll);

const cz = 0.62, fit = 0.60;
const view = Math.min(BW, BH) * 0.30 * (0.4 + P.scale * 1.4);
const hbw = BW * 0.5, hbh = BH * 0.5;

// fade the density field (trail persistence)
const decay = 0.72 + P.persist * 0.24;
for (let i = 0, n = BW * BH; i < n; i++) { dens[i] *= decay; chr[i] *= decay; zdp[i] *= decay; }

// integrate the Aizawa ODE 45k-90k steps/frame and splat bright into the fading buffer
let x = S.px, y = S.py, z = S.pz;
const steps = Math.round(45000 + P.density * 45000);
for (let s = 0; s < steps; s++) {
  const dx = (z - bv) * x - dC * y;
  const dy = dC * x + (z - bv) * y;
  const dz = cC + av * z - (z * z * z) / 3 - (x * x + y * y) * (1 + eC * z) + fC * z * x * x * x;
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (!(x > -1e4 && x < 1e4) || !(y > -1e4 && y < 1e4) || !(z > -1e4 && z < 1e4)) { x = 0.05; y = 0; z = 0; continue; }
  const rxy = Math.sqrt(x * x + y * y);
  const nx = x * fit, ny = y * fit, nz = (z - cz) * fit;
  // yaw (Y) -> pitch (X) -> roll (Z, screen plane)
  const px1 = nx * cY - nz * sY, pz1 = nx * sY + nz * cY;
  const py1 = ny * cP - pz1 * sP, pz2 = ny * sP + pz1 * cP;
  const sx = px1 * cR - py1 * sR, sy = px1 * sR + py1 * cR;
  const bxi = (hbw + sx * view) | 0, byi = (hbh - sy * view) | 0;
  if (bxi >= 0 && bxi < BW && byi >= 0 && byi < BH) {
    const bi = byi * BW + bxi;
    dens[bi] += 1;
    chr[bi] += Math.min(1, rxy * 0.74);        // 0 near polar spiral (gold) -> 1 on equatorial shell (indigo)
    zdp[bi] += pz2 * 0.5 + 0.5;                 // view depth for shading
  }
}
S.px = x; S.py = y; S.pz = z;

const hueBase = (P.hue + S.hoff * 40 + sec * 10) % 360;
const expo = 0.45 + P.energy * 2.4 + P.density * 0.5 + K.intensity * 0.4 + A.bass * 1.4;

g.loadPixels();
const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const cyn = j / BH - 0.5;
  for (let i = 0; i < BW; i++) {
    const bi = j * BW + i;
    const d = dens[bi];
    const dn = 1 - Math.exp(-d * expo * 0.038);      // log-density tone map -> the whole form glows
    const avgc = d > 0.0001 ? chr[bi] / d : 1;
    const avgz = d > 0.0001 ? zdp[bi] / d : 0.5;
    const cxn = i / BW - 0.5;
    const vig = Math.exp(-(cxn * cxn + cyn * cyn) * 2.5);
    const shade = 0.55 + 0.5 * avgz;
    let r, gg, b;
    if (styleI === 1) { // plasma: magenta polar spiral -> cyan shell
      const spir = [1.0, 0.12, 0.86], shell = [0.10, 0.92, 1.0];
      const br = Math.min(1, dn * shade * 1.15);
      const gnd = 0.05 * vig;
      r = Math.min(1, gnd * 0.9 + (spir[0] + (shell[0] - spir[0]) * avgc) * br);
      gg = Math.min(1, gnd * 0.3 + (spir[1] + (shell[1] - spir[1]) * avgc) * br);
      b = Math.min(1, gnd * 1.1 + (spir[2] + (shell[2] - spir[2]) * avgc) * br);
    } else if (styleI === 2) { // ember: blackbody heat ramp
      const m = Math.min(1, dn * shade * 1.2);
      r = Math.min(1, m * 2.0);
      gg = Math.min(1, Math.max(0, m * 1.75 - 0.5));
      b = Math.min(1, Math.max(0, m * 3.1 - 2.35));
      const lift = 0.05 * vig; r = Math.min(1, r + lift * 0.9); gg = Math.min(1, gg + lift * 0.3); b = Math.min(1, b + lift * 0.05);
    } else if (styleI === 3) { // ice: deep blue -> white-hot
      const cold = [0.14, 0.34, 0.85], hot = [0.95, 0.98, 1.0];
      const t2 = Math.min(1, dn * shade);
      const gnd = 0.05 * vig;
      r = Math.min(1, gnd * 0.4 + (cold[0] + (hot[0] - cold[0]) * t2) * (0.15 + 0.9 * t2));
      gg = Math.min(1, gnd * 0.6 + (cold[1] + (hot[1] - cold[1]) * t2) * (0.2 + 0.9 * t2));
      b = Math.min(1, gnd * 1.0 + (cold[2] + (hot[2] - cold[2]) * t2) * (0.35 + 0.75 * t2));
    } else if (styleI === 4) { // pencil: graphite spiral on toned paper (mono, abstracted)
      const grain = 0.86 + 0.28 * (Math.abs(Math.sin(i * 12.9 + j * 78.2) * 43758.5) % 1);
      const ink = Math.min(1, Math.pow(dn, 0.82) * grain);
      const paper = 0.9 - (1 - vig) * 0.08;
      const tone = paper - ink * 0.84;
      r = tone * 0.99; gg = tone * 0.965; b = tone * 0.9;
    } else { // cosmic (default): gold polar spiral -> indigo shell, glowing on deep-space ground
      const gold = [1.0, 0.80, 0.30], indigo = [0.34, 0.20, 0.9];
      const br = Math.min(1, dn * shade * 1.15);
      const gR = 0.04 + 0.05 * vig, gG = 0.03 + 0.035 * vig, gB = 0.09 + 0.12 * vig;
      r = Math.min(1, gR + (gold[0] + (indigo[0] - gold[0]) * avgc) * br);
      gg = Math.min(1, gG + (gold[1] + (indigo[1] - gold[1]) * avgc) * br);
      b = Math.min(1, gB + (gold[2] + (indigo[2] - gold[2]) * avgc) * br);
    }
    const o = 4 * bi;
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom on bass/treble — partial ADD tint, never full-frame flash (won't strobe)
if (styleI !== 4 && (A.bass > 0.02 || A.treble > 0.02)) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass * 0.5 + A.treble * 0.35) * (0.4 + P.energy * 0.6);
  fill((hueBase + 25) % 360, 45, 100, glow * 20);
  ellipse(P.x * width, P.y * height, width * 0.85, height * 0.85);
  blendMode(BLEND); pop();
}
